function validate([nums1, nums2]) {
  if (!Array.isArray(nums1) || nums1.length > 1000) return 'nums1 has at most 1000 values.';
  if (!Array.isArray(nums2) || nums2.length < 1 || nums2.length > 1000) return 'nums2 needs 1 to 1000 values.';
  if (nums1.some(v => v !== 0 && v !== 1) || nums2.some(v => v !== 0 && v !== 1)) return 'Every value is 0 or 1.';
  return null;
}

