function minLargest(nums1, nums2) {
  const m = nums1.length;
  const n = nums2.length;
  const nextAbove = (value, bit) => ((value + 1) % 2 === bit ? value + 1 : value + 2);
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let j = 1; j <= n; j++) {
    dp[0][j] = nextAbove(dp[0][j - 1], nums2[j - 1]);
  }
  for (let i = 1; i <= m; i++) {
    dp[i][0] = nextAbove(dp[i - 1][0], nums1[i - 1]);
    for (let j = 1; j <= n; j++) {
      const viaNums1 = nextAbove(dp[i - 1][j], nums1[i - 1]);
      const viaNums2 = nextAbove(dp[i][j - 1], nums2[j - 1]);
      dp[i][j] = Math.min(viaNums1, viaNums2);
    }
  }
  return dp[m][n];
}

