function minLargest(nums1, nums2) {
  // Hand out 1, 2, 3, ... in turn; reach holds every (i, j) that can be filled using the integers so far.
  let reach = new Set(['0,0']);
  for (let value = 1; ; value++) {
    const grown = new Set(reach);
    for (const key of reach) {
      const [i, j] = key.split(',').map(Number);
      if (i < nums1.length && nums1[i] === value % 2) grown.add(i + 1 + ',' + j);
      if (j < nums2.length && nums2[j] === value % 2) grown.add(i + ',' + (j + 1));
    }
    reach = grown;
    if (reach.has(nums1.length + ',' + nums2.length)) return value;
  }
}

