function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const m = large ? int(700, 1000) : int(0, 6);
  const n = large ? int(700, 1000) : int(1, 6);
  // Each array leans towards ones by its own random amount, from all zeros to all ones.
  const bits = (length) => {
    const lean = rand();
    return Array.from({ length }, () => (rand() < lean ? 1 : 0));
  };
  return [bits(m), bits(n)];
}
